import gzip, re
for f in ['res_1vs97.rds','res_1vs98.rds']:
    p='/workspace/staged/'+f
    raw=gzip.open(p,'rb').read()
    strings=[]
    for m in re.finditer(rb'[ -~]{3,}', raw):
        s=m.group().decode('latin1')
        if not re.match(r'"'^PA14_'"\\d{5}"'$'"', s) and not re.match(r'"'^['"\\d.eE+-]+"'$'"', s):
            strings.append(s)
    # unique
    seen=set(); out=[]
    for s in strings:
        if s not in seen:
            seen.add(s); out.append(s)
    print('\\nFILE',f,'unique strings',len(out))
    for s in out[:300]: print(repr(s))
PY"

